FuncDef.Code:
float opInfRepeatXZ(inout vec3 p, float spacingX, float spacingZ)
{
    vec2 spacing = vec2(spacingX, spacingZ);
    vec2 halfsize = spacing*0.5;
    vec2 c = floor((p.xz + halfsize)/spacing);
    float cellIndex = c.x + c.y + PI * sin(c.x * c.y);
    p.xz = mod(p.xz + halfsize, spacing) - halfsize;

    return cellIndex;
}
